#[allow(unused_variables)] fn ability_1_target_0(q: &dyn Query, asker: &Asker, t: Target) -> bool { q.state().stack.iter().any(|e| (match t { Target::Object(id) => e.kind == StackKind::Spell && e.object == id, Target::Ability(serial) => e.kind != StackKind::Spell && e.serial == serial, _ => false }) && ((e.kind == StackKind::Activated || e.kind == StackKind::Triggered || (e.kind == StackKind::Spell && !((e.kind == StackKind::Spell && q.chars(e.object).is(CardType::Creature))))))) }
